schema:
CREATE TABLE VIEWS (
    ARTICLE_ID INT,
    AUTHOR_ID INT,
    VIEWER_ID INT,
    VIEW_DATE DATE
);

CREATE TABLE SALESPERSON (
    SALES_ID INT,
    NAME VARCHAR(255),
    SALARY INT,
    COMMISSION_RATE INT,
    HIRE_DATE VARCHAR(255)
);

CREATE TABLE COMPANY (
    COM_ID INT,
    NAME VARCHAR(255),
    CITY VARCHAR(255)
);

CREATE TABLE ORDERS (
    ORDER_ID INT,
    COM_ID INT,
    SALES_ID INT,
    ORDER_DATE VARCHAR(255),
    AMOUNT INT
);

CREATE TABLE CUSTOMERS (
    ID INT,
    NAME VARCHAR(255),
    PRIMARY KEY (ID)
);

CREATE TABLE ORDERS (
    ID INT,
    CUSTOMERID INT,
    PRIMARY KEY (ID),
    FOREIGN KEY (CUSTOMERID) REFERENCES CUSTOMERS(ID)
);

counterexample:
INSERT INTO CUSTOMERS (ID, NAME) VALUES (1, 'Alice');
INSERT INTO ORDERS (ID, CUSTOMERID) VALUES (1, 1);
INSERT INTO ORDERS (ID, CUSTOMERID) VALUES (2, 1);

